#requires -Version 7.0
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'Initialize-TemporaryFiles.ps1')
$queueSource=[IO.File]::ReadAllText((Join-Path $PSScriptRoot '../../Scripts/Crafting/UI/RebirthStationGridQueue.cs'))
function QueueMethod([string]$signature){$start=$queueSource.IndexOf($signature);if($start-lt 0){throw $signature};$brace=$queueSource.IndexOf('{',$start);$depth=1;$end=$brace+1;while($depth-gt 0){if($queueSource[$end]-eq '{'){$depth++};if($queueSource[$end]-eq '}'){$depth--};$end++};$queueSource.Substring($start,$end-$start)}
$queueSlice="public static class RebirthStationGridQueue {public const string Prefix=`"rebirth.station.queue.`";private sealed class DefinitionState{internal bool Resolved;}private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<Recipe,DefinitionState> Definitions=new System.Runtime.CompilerServices.ConditionalWeakTable<Recipe,DefinitionState>();public static bool IsMarked(Recipe r)=>r?.ingredients?.Count>0&&r.ingredients[0].itemValue.HasMetadata(Prefix+`"version`");"
foreach($signature in @('private static string DefinitionKey(','public static bool Stamp(','private static bool TryResolveDefinition(','public static bool ConservesPayment(','public static ItemStack RefundSnapshot(')){$queueSlice+=QueueMethod $signature}
$queueSlice+='public static bool Resolve(Recipe r,IList<Recipe> d)=>TryResolveDefinition(r,d,out _,out _,out _);}'
$queueFixture=@'
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;
public class ItemValue{public int type;public Dictionary<string,object> Metadata=new Dictionary<string,object>();public bool IsEmpty()=>type==0;public bool HasMetadata(string k)=>Metadata.ContainsKey(k);public void SetMetadata(string k,object v){Metadata[k]=v;}public bool TryGetMetadata<T>(string k,out T v){v=default(T);if(!Metadata.TryGetValue(k,out var o)||!(o is T))return false;v=(T)o;return true;}public ItemValue Clone()=>new ItemValue{type=type,Metadata=new Dictionary<string,object>(Metadata)};}
public class ItemStack{public ItemValue itemValue;public int count;public ItemStack(ItemValue v,int c){itemValue=v;count=c;}public ItemStack Clone()=>new ItemStack(itemValue.Clone(),count);}
public class Recipe{public int itemValueType=5,count=1,craftExpGain=3,craftingToolType;public float craftingTime=1;public string craftingArea="forge",tags="forge";public bool IsScrap,materialBasedRecipe,UseIngredientModifier,wildcardForgeCategory,wildcardCampfireCategory;public List<ItemStack> ingredients=new List<ItemStack>();public void Write(BinaryWriter w){w.Write(itemValueType);w.Write(count);w.Write(craftExpGain);w.Write(craftingTime);w.Write(craftingArea);foreach(var i in ingredients){w.Write(i.itemValue.type);w.Write(i.count);}}}
public class Writer:BinaryWriter{public Writer():base(new MemoryStream()){}public void SetBaseStream(Stream s){OutStream=s;}}
public class Pool{public Writer AllocSync(bool b)=>new Writer();}public static class MemoryPools{public static Pool poolBinaryWriter=new Pool();}
public static class RebirthStationGridIngredients{public static bool IsSameStackSnapshot(ItemStack a,ItemStack b)=>a.count==b.count&&a.itemValue.type==b.itemValue.type&&a.itemValue.Metadata.Count==b.itemValue.Metadata.Count&&a.itemValue.Metadata.All(p=>b.itemValue.Metadata.TryGetValue(p.Key,out var v)&&Equals(p.Value,v));}
public static class MaterialQueueFixture{
static void Check(bool v,string n){if(!v)throw new Exception(n);}static ItemStack Cell(int t,int c)=>new ItemStack(new ItemValue{type=t},c);
public static void Run(){foreach(bool perBatch in new[]{false,true}){var source=new Recipe{materialBasedRecipe=true};source.ingredients.Add(Cell(11,1000));var queue=new Recipe{count=perBatch?1:100,craftExpGain=perBatch?3:300,craftingTime=perBatch?1:100};queue.ingredients.Add(Cell(11,100000));
Check(RebirthStationGridQueue.Stamp(queue,source,100,0,perBatch)&&queue.ingredients[0].count==1&&(int)queue.ingredients[0].itemValue.Metadata[RebirthStationGridQueue.Prefix+"materialUnits"]==100000&&!queue.materialBasedRecipe,"native count-safe material marker");Check(RebirthStationGridQueue.Resolve(queue,new[]{source}),"exact material definition rejected");var before=new[]{Cell(0,0),Cell(0,0),Cell(0,0),Cell(11,100000),Cell(12,0)};var after=new[]{Cell(0,0),Cell(0,0),Cell(0,0),Cell(11,0),Cell(12,0)};Check(RebirthStationGridQueue.ConservesPayment(before,after,queue),"typed zero/full Int32 conservation rejected");var refund=RebirthStationGridQueue.RefundSnapshot(queue.ingredients[0]);Check(refund.count==100000&&refund.itemValue.Metadata.Count==0&&queue.ingredients[0].count==1,"refund clipped or mutated marker");queue.ingredients[0].itemValue.Metadata[RebirthStationGridQueue.Prefix+"materialUnits"]=100001;Check(!RebirthStationGridQueue.ConservesPayment(before,after,queue),"extra units passed conservation");queue.ingredients[0].itemValue.Metadata[RebirthStationGridQueue.Prefix+"materialUnits"]=0;Check(!RebirthStationGridQueue.Resolve(queue,new[]{source}),"invalid units passed definition validation");}
var physical=new Recipe{craftingArea="workbench"};physical.ingredients.Add(Cell(1,2));var concrete=new Recipe{craftingArea="workbench",count=2,craftExpGain=6,craftingTime=2};concrete.ingredients.Add(Cell(1,4));Check(RebirthStationGridQueue.Stamp(concrete,physical,2,0)&&(int)concrete.ingredients[0].itemValue.Metadata[RebirthStationGridQueue.Prefix+"version"]==1&&concrete.ingredients[0].count==4&&RebirthStationGridQueue.Resolve(concrete,new[]{physical}),"physical legacy v1 changed");var perPhysical=new Recipe{craftingArea="workbench",count=1,craftExpGain=3,craftingTime=1};perPhysical.ingredients.Add(Cell(1,4));Check(RebirthStationGridQueue.Stamp(perPhysical,physical,2,0,true)&&(int)perPhysical.ingredients[0].itemValue.Metadata[RebirthStationGridQueue.Prefix+"version"]==3&&perPhysical.count==1&&perPhysical.craftExpGain==3&&RebirthStationGridQueue.Resolve(perPhysical,new[]{physical}),"physical perbatch v3 retains one native output and full payment");Console.WriteLine("PASS actual queue material v2/v4 and physical v1: Int32 metadata/native-safe counts, exact catalogue flags/hash, typed-zero conservation, detached refund, altered/zero units denial, legacy physical behavior. Native recipe/item codec doubled.");}}
'@
Add-Type -TypeDefinition ($queueFixture+"`n"+$queueSlice)
[MaterialQueueFixture]::Run()
